changeSet.sql:
ALTER TABLE exercise
    ADD COLUMN is_public BOOLEAN NOT NULL DEFAULT FALSE;

CREATE INDEX idx_exercise_is_public ON exercise (is_public);

ALTER TABLE exercise
    ADD COLUMN guid BINARY(16) NULL;

UPDATE exercise
    SET guid = UNHEX(MD5(CONCAT('exercise-model-', id)))
    WHERE guid IS NULL;

ALTER TABLE exercise
    MODIFY COLUMN guid BINARY(16) NOT NULL;

CREATE UNIQUE INDEX unq_exercise_guid ON exercise (guid);
